from itertools import compress

def solve(n):
    # All primes strictly below n. bytearray sieve with slice assignment
    # for speed and low memory on large n.
    if n is None or n <= 2:
        return []
    n = int(n)
    sieve = bytearray([1]) * n
    sieve[0:2] = b"\x00\x00"
    for i in range(2, int(n ** 0.5) + 1):
        if sieve[i]:
            step_count = len(range(i * i, n, i))
            sieve[i * i::i] = bytearray(step_count)
    return list(compress(range(n), sieve))

