import math

def solve(n):
    # Count of primes strictly below n, computed with a segmented bytearray
    # sieve (fast, low memory even for very large n). Robust to inputs
    # given as bool/str/float representations of a number.
    if n is None:
        return 0
    if isinstance(n, bool):
        v = int(n)
    elif isinstance(n, int):
        v = n
    elif isinstance(n, float):
        if not math.isfinite(n):
            return 0
        v = n
    elif isinstance(n, str):
        s = n.strip()
        try:
            v = int(s)
        except ValueError:
            try:
                v = float(s)
            except ValueError:
                return 0
    else:
        return 0
    if v <= 2:
        return 0
    if isinstance(v, float):
        size = int(v) if v == int(v) else int(math.floor(v)) + 1
    else:
        size = v
    if size <= 2:
        return 0
    root = math.isqrt(size - 1)
    base = bytearray([1]) * (root + 1)
    base[0:2] = b"\x00\x00"
    for i in range(2, math.isqrt(root) + 1):
        if base[i]:
            base[i * i::i] = bytearray(len(range(i * i, root + 1, i)))
    base_primes = [i for i in range(2, root + 1) if base[i]]
    count = len(base_primes)
    SEG = 1 << 20
    low = root + 1
    while low < size:
        high = min(low + SEG, size)
        seg = bytearray([1]) * (high - low)
        for p in base_primes:
            start = max(p * p, ((low + p - 1) // p) * p)
            if start < high:
                seg[start - low::p] = bytearray(len(range(start, high, p)))
        count += sum(seg)
        low = high
    return count

