def solve(*args, **kwargs):
    # Merge overlapping or touching intervals; result sorted by start.
    # Accept intervals positionally or via a keyword argument so callers
    # using either convention work; the merge logic itself is canonical.
    intervals = None
    if args:
        intervals = args[0]
    else:
        for name in ("intervals", "ivs", "interval_list", "data", "lst", "input"):
            if name in kwargs:
                intervals = kwargs[name]
                break
        if intervals is None and kwargs:
            intervals = next(iter(kwargs.values()))
    if not intervals:
        return []
    ivs = sorted(intervals, key=lambda iv: (iv[0], iv[1]))
    merged = [list(ivs[0])]
    for start, end in ivs[1:]:
        if start <= merged[-1][1]:
            if end > merged[-1][1]:
                merged[-1][1] = end
        else:
            merged.append([start, end])
    return merged

