def solve(matrix):
    """Return the determinant of a square integer matrix.
    Empty matrix has determinant 1.
    Uses Bareiss algorithm for exact integer arithmetic.
    """
    n = len(matrix)
    if n == 0:
        return 1
    # copy to mutable list of lists
    a = [row[:] for row in matrix]
    det_sign = 1
    for k in range(n - 1):
        # pivot if zero
        if a[k][k] == 0:
            for i in range(k + 1, n):
                if a[i][k] != 0:
                    a[k], a[i] = a[i], a[k]
                    det_sign = -det_sign
                    break
            else:
                return 0
        for i in range(k + 1, n):
            for j in range(k + 1, n):
                a[i][j] = (a[i][j] * a[k][k] - a[i][k] * a[k][j])
                if k > 0:
                    a[i][j] //= a[k - 1][k - 1]
            a[i][k] = 0
    return det_sign * a[n - 1][n - 1]

