    """Count the number of islands in a 2D grid.
    grid is a list of lists of 0/1 integers (or booleans/strings '0'/'1').
    An island is a group of adjacent 1s horizontally or vertically.
    Returns integer count.
    """
    if not grid:
        return 0
    rows = len(grid)
    cols = len(grid[0]) if rows else 0
    # Normalize cells to int 1 or 0
    def is_land(r, c):
        val = grid[r][c]
        if isinstance(val, str):
            return val == '1'
        return bool(val)
    visited = [[False] * cols for _ in range(rows)]
    def dfs(r, c):
        stack = [(r, c)]
        while stack:
            x, y = stack.pop()
            if visited[x][y]:
                continue
            visited[x][y] = True
            for dx, dy in ((1,0), (-1,0), (0,1), (0,-1)):
                nx, ny = x+dx, y+dy
                if 0 <= nx < rows and 0 <= ny < cols and not visited[nx][ny] and is_land(nx, ny):
                    stack.append((nx, ny))
    count = 0
    for i in range(rows):
        for j in range(cols):
            if not visited[i][j] and is_land(i, j):
                dfs(i, j)
                count += 1
    return count
