{"task_id": "T49", "code": "from collections import deque

def solve(grid, *rest, **kwargs):
    # Shortest path length (number of moves, 4-directional) from top-left
    # to bottom-right of a 0/1 grid where 0 = open, 1 = blocked; -1 if the
    # end is unreachable. start/end corner points are implicit but an
    # explicit start/end may optionally be passed.
    if not grid or not grid[0]:
        return -1
    n, m = len(grid), len(grid[0])
    start = rest[0] if len(rest) >= 1 else kwargs.get("start", (0, 0))
    end = rest[1] if len(rest) >= 2 else kwargs.get("end", (n - 1, m - 1))
    si, sj = start
    ei, ej = end
    if grid[si][sj] == 1 or grid[ei][ej] == 1:
        return -1
    if (si, sj) == (ei, ej):
        return 0
    dist = [[-1] * m for _ in range(n)]
    dist[si][sj] = 0
    q = deque([(si, sj)])
    while q:
        i, j = q.popleft()
        for di, dj in ((1, 0), (-1, 0), (0, 1), (0, -1)):
            ni, nj = i + di, j + dj
            if 0 <= ni < n and 0 <= nj < m and grid[ni][nj] == 0 and dist[ni][nj] == -1:
                dist[ni][nj] = dist[i][j] + 1
                if (ni, nj) == (ei, ej):
                    return dist[ni][nj]
                q.append((ni, nj))
    return -1"}

