def solve(nums):
    """Return length of longest strictly increasing subsequence of nums.
    Uses patience sorting O(n log n).
    """
    import bisect
    tails = []
    for x in nums:
        # find position to replace
        i = bisect.bisect_left(tails, x)
        if i == len(tails):
            tails.append(x)
        else:
            tails[i] = x
    return len(tails)

def solve(tokens):
    """Evaluate Reverse Polish Notation expression.
    Tokens are strings representing integers or '+', '-', '*', '/'.
    Division truncates toward zero as in classic LeetCode problem.
    """
    stack = []
    for tok in tokens:
        if tok in ('+', '-', '*', '/'):
            b = stack.pop()
            a = stack.pop()
            if tok == '+':
                res = a + b
            elif tok == '-':
                res = a - b
            elif tok == '*':
                res = a * b
            else:  # division
                # Truncate toward zero
                if b == 0:
                    raise ZeroDivisionError('division by zero')
                res = int(a / b)  # int() truncates toward zero in Python
            stack.append(res)
        else:
            # integer token, may be negative
            stack.append(int(tok))
    return stack[0] if stack else 0

