    import heapq
    if args and isinstance(args[0], (int, float)) and len(args) >= 2:
        n = args[0]; edges = args[1]
    elif len(args) == 2 and isinstance(args[1], (list, tuple)):
        n, edges = args
    else:
        n = None; edges = args[0]
    graph = {}
    indeg = {}
    def add_node(x):
        indeg.setdefault(x, 0)
    if isinstance(edges, dict):
        for u, vs in edges.items():
            add_node(u)
            graph.setdefault(u, [])
            for v in vs:
                add_node(v)
                graph.setdefault(u, []).append(v)
                indeg[v] = indeg.get(v, 0) + 1
    else:
        for e in edges:
            u, v = e[0], e[1]
            add_node(u); add_node(v)
            graph.setdefault(u, []).append(v)
            indeg[v] += 1
    if n is not None:
        n = int(n)
        labels = set(indeg)
        if any(l == 0 for l in labels):
            for i in range(n): add_node(i)
        elif all(isinstance(l, int) and 1 <= l <= n for l in labels):
            for i in range(1, n + 1): add_node(i)
        else:
