def solve(*args):
    """Return the lexicographically smallest topological ordering.
    Accepts either solve(n, edges) or solve(edges) where edges is a list of
    [a, b] pairs. In the single-argument form n is inferred as max node + 1.
    If a cycle exists, returns an empty list.
    """
    import heapq
    if len(args) == 2:
        n, edges = args
    elif len(args) == 1:
        edges = args[0]
        max_node = -1
        for a, b in edges:
            if a > max_node:
                max_node = a
            if b > max_node:
                max_node = b
        n = max_node + 1 if max_node >= 0 else 0
    else:
        raise TypeError('solve expects 1 or 2 arguments')
    # Build adjacency list and indegree count
    adj = [[] for _ in range(n)]
    indeg = [0] * n
    for a, b in edges:
        if 0 <= a < n and 0 <= b < n:
            adj[a].append(b)
            indeg[b] += 1
    # Initialize min-heap with all zero-indegree nodes
    heap = [i for i in range(n) if indeg[i] == 0]
    heapq.heapify(heap)
    order = []
    while heap:
        u = heapq.heappop(heap)
        order.append(u)
        for v in adj[u]:
            indeg[v] -= 1
            if indeg[v] == 0:
                heapq.heappush(heap, v)
    if len(order) != n:
        return []
    return order

