from collections import deque

def solve(grid):
    # Count connected components of 1s (4-directional) via BFS.
    if not grid or not grid[0]:
        return 0
    n, m = len(grid), len(grid[0])
    seen = [[False] * m for _ in range(n)]
    count = 0
    for i in range(n):
        for j in range(m):
            if grid[i][j] == 1 and not seen[i][j]:
                count += 1
                seen[i][j] = True
                q = deque([(i, j)])
                while q:
                    ci, cj = q.popleft()
                    for di, dj in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                        ni, nj = ci + di, cj + dj
                        if 0 <= ni < n and 0 <= nj < m and grid[ni][nj] == 1 and not seen[ni][nj]:
                            seen[ni][nj] = True
                            q.append((ni, nj))
    return count

