def solve(tokens):
    """Evaluate Reverse Polish Notation expression.
    Supports '+', '-', '*', '/' where division truncates toward zero.
    Tokens are strings representing integers or operators.
    """
    stack = []
    for token in tokens:
        if token in ('+', '-', '*', '/'):
            b = stack.pop()
            a = stack.pop()
            if token == '+':
                res = a + b
            elif token == '-':
                res = a - b
            elif token == '*':
                res = a * b
            else:  # division truncates toward zero
                # Python's int division truncates toward zero when using int()
                res = int(a / b)
            stack.append(res)
        else:
            stack.append(int(token))
    return stack[0] if stack else 0

