def solve(s):
    if not s:
        return ''
    n=len(s)
    start=0
    max_len=1
    def expand(l,r):
        while l>=0 and r<n and s[l]==s[r]:
            l-=1; r+=1
        return l+1, r-1
    for i in range(n):
        l1,r1=expand(i,i)
        len1=r1-l1+1
        if len1>max_len:
            start=l1; max_len=len1
        l2,r2=expand(i,i+1)
        len2=r2-l2+1
        if len2>max_len:
            start=l2; max_len=len2
    return s[start:start+max_len]

