def solve(ip):
    """Validate IPv4 address.
    Accepts str, bytes, or bytearray. Returns True if the address consists of
    four decimal numbers 0-255 without leading zeros (except the digit "0").
    Any other type returns False.
    """
    # Normalize input to string
    if isinstance(ip, (bytes, bytearray)):
        try:
            ip = ip.decode()
        except Exception:
            # fallback: interpret each byte as a character
            ip = ''.join(chr(b) for b in ip)
    elif not isinstance(ip, str):
        return False
    parts = ip.split('.')
    if len(parts) != 4:
        return False
    for part in parts:
        # each part must be non-empty and all digits
        if not part or not part.isdigit():
            return False
        # no leading zeros unless the part is exactly "0"
        if len(part) > 1 and part[0] == '0':
            return False
        val = int(part)
        if val < 0 or val > 255:
            return False
    return True

