def solve(s):
    if not isinstance(s, str):
        return False
    parts = s.split('.')
    if len(parts) != 4:
        return False
    for p in parts:
        if not p:
            return False
        for ch in p:
            if ch not in '0123456789':
                return False
        if len(p) > 1 and p[0] == '0':
            return False
        if int(p) > 255:
            return False
    return True
